"""Original Go exercises following the Tour, specification, and standard library."""
from build import S, lesson as L


def lessons():
 return [
 L('tooling','Modules and the Go toolchain','A module is versioned source identified by go.mod. Packages organize code inside it. go run builds and runs; go test runs package tests; gofmt formats source without changing its intended meaning. package main with func main defines an executable.',
 S('$ go ~mod init~ example.com/${word}','Creates a module declaration','Runs the server|Publishes a module','go mod init writes go.mod for the chosen module path.','run|test','What does this command establish?'),
 S('$ go ~test~ ./...','Tests packages recursively under the current directory','Publishes dependencies|Only formats files','The ./... pattern selects the package tree for the test command.','build|fmt','What is requested?'),
 S('~package~ main\nfunc main() {}','Declares an executable package','Imports a package named main|Creates a thread','package main identifies the executable package; main is its entry function.','import|module','What does the first line declare?'),
 S('$ ~gofmt~ -w main.go','Formats main.go in place','Executes main.go|Runs the race detector','gofmt -w writes formatted Go source back to the named file.','go run|go test','What happens to the source?')),
 L('bindings','Short declarations and zero values','var initializes to the type zero value when no expression is supplied. := declares locals with inferred types and needs at least one new nonblank variable in its scope. Constants differ from variables. Go requires explicit conversion between distinct numeric types.',
 S('var n int; fmt.Println(~n~)','0','nil|Compile error','The zero value of int is zero.','n+1|true'),
 S('n ~:=~ ${n}; n++; fmt.Println(n)','${next}','${n}|Compile error','A short declaration introduces n; increment then updates it.','=|=='),
 S('var n int32=${n}; fmt.Println(~int(n)~+1)','${next}','Compile error|${n}','An explicit conversion changes int32 to int.','n==1|string(n)'),
 S('const n=${n}; fmt.Println(~n+1~)','${next}','${n}|0','A constant can participate in a constant arithmetic expression.','n|0')),
 L('text','Bytes, runes, and strings','Strings are immutable byte sequences. len counts bytes; rune represents a Unicode code point. Ranging over a string decodes UTF-8 runes. Conversion to []rune is useful for code-point operations, which are still not grapheme-cluster operations.',
 S('fmt.Println(len(~"${word}"~))','${length}','0|Compile error','The generated ASCII word uses one byte per character.','""|"x"'),
 S('fmt.Println(len(~[]rune("λ")~))','1','2|Compile error','The Greek letter is one rune but occupies two UTF-8 bytes.','"λ"|[]byte("λ")'),
 S('fmt.Println(strings.~ToUpper~("${word}"))','${upper}','${word}|Compile error','ToUpper returns a new uppercase string.','ToLower|TrimSpace'),
 S('n,err:=strconv.~Atoi~("${n}"); fmt.Println(n+1,err==nil)','${next} true','${n} false|Compile error','Atoi returns both the parsed int and an error; valid decimal input has nil error.','Itoa|Quote')),
 L('control','If, switch, and short-circuiting','Conditions require bool. An if initializer scopes a value to the branch chain. Switch cases do not fall through unless explicitly requested. Logical operators short-circuit, so the second expression may never execute.',
 S('if n:=${n}; n ~>~ 0 {fmt.Println(n)}','${n}','No output|Compile error','The initializer declares n for the conditional and its branches.','<|=='),
 S('switch ${n} {case ${n}: fmt.Println("yes"); ~default~: fmt.Println("no")}','yes','yes\nno|no','A matched case exits this switch without implicit fall-through.','else|otherwise'),
 S('called:=false; check:=func()bool{called=true;return true}; _=false ~&&~ check(); fmt.Println(called)','false','true|Compile error','The call is skipped because the left side is false.','|||=='),
 S('n:=${n}; switch {case n>0: fmt.Println("positive"); ~default~: fmt.Println("other")}','positive','other|Compile error','A switch without a tag tests boolean cases in order.','else|case')),
 L('iteration','For, range, and loop values','Go has for as its loop construct. range over a slice yields an index and a copied element. Assigning that copied element does not update the slice. Continue skips one iteration; break exits the loop.',
 S('n:=0; for i:=0;i<${n};i++ {n++}; fmt.Println(~n~)','${n}','${next}|0','The counted loop runs ${n} times.','0|n+1'),
 S('a:=[]int{${n}}; for _,v:=range a {v++; _=v}; fmt.Println(a[~0~])','${n}','${next}|Compile error','v holds a copy of the element; mutate a[i] to update the slice.','1|2'),
 S('a:=[]int{${n},${m}}; for i:=range a {a[i]++}; fmt.Println(~a[0]~)','${next}','${n}|0','Indexing the slice updates its backing elements.','a[1]|len(a)'),
 S('n:=0; for i:=0;i<3;i++ {if i==1 {~continue~}; n++}; fmt.Println(n)','2','1|3','continue skips the middle increment but allows the next iteration.','break|return')),
 L('functions','Multiple returns and variadic arguments','Functions may return several values, making explicit result/error pairs natural. Variadic parameters collect extra arguments into a slice; ... expands a slice at a call site. Named results exist but explicit return values often make code clearer.',
 S('f:=func(n int) ~int~ {return n+1}; fmt.Println(f(${n}))','${next}','${n}|Compile error','The return type is written after the parameter list.','string|bool'),
 S('f:=func()(int,bool){return ${n},true}; n,ok:=~f()~; fmt.Println(n,ok)','${n} true','0 false|Compile error','Both returned values are bound by the assignment.','f|nil'),
 S('f:=func(xs ~...int~)int{return len(xs)}; fmt.Println(f(${n},${m}))','2','1|Compile error','A variadic parameter receives the two arguments as a slice.','int|[]int'),
 S('f:=func(xs ...int)int{return len(xs)}; a:=[]int{${n},${m}}; fmt.Println(f(~a...~))','2','1|Compile error','The call-site ellipsis expands a slice into variadic arguments.','a|...a')),
 L('slices','Slice length, capacity, and aliasing','A slice describes a region of a backing array. Reslicing shares storage; copy transfers elements into different storage. append returns an updated slice and may allocate a new backing array. Never assume aliasing after append without considering capacity.',
 S('a:=[]int{${n},${m}}; b:=a[:1]; b[0]=0; fmt.Println(~a[0]~)','0','${n}|Compile error','Both slices refer to the same first backing-array element.','a[1]|len(a)'),
 S('a:=make([]int,1,3); fmt.Println(len(a),~cap(a)~)','1 3','3 3|1 1','Length counts accessible elements; capacity limits reslicing and in-place append.','len(a)|a[0]'),
 S('a:=[]int{${n}}; a=~append~(a,${m}); fmt.Println(len(a))','2','1|Compile error','Use the returned slice because its length and backing array may change.','copy|make'),
 S('a:=[]int{${n}}; b:=make([]int,1); ~copy~(b,a); b[0]=0; fmt.Println(a[0])','${n}','0|Compile error','copy moves elements into b independent of the original backing array.','append|delete')),
 L('maps','Map lookup and absent keys','A map lookup returns a zero value when the key is absent; comma-ok distinguishes absence from a stored zero. Reading a nil map works, but assigning into one panics. Iteration order is unspecified, so output questions must not rely on it.',
 S('m:=map[string]int{}; n,ok:=~m["${word}"]~; fmt.Println(n,ok)','0 false','0 true|Compile error','Comma-ok reports that this key is missing.','len(m)|nil'),
 S('m:=~make(map[string]int)~; m["${word}"]=${n}; fmt.Println(m["${word}"])','${n}','0|Compile error','make creates a writable empty map.','map[string]int(nil)|nil'),
 S('m:=map[string]int{"${word}":${n}}; ~delete~(m,"${word}"); fmt.Println(len(m))','0','1|Compile error','delete removes the mapping and is harmless for absent keys.','clear|append'),
 S('var m map[string]int; fmt.Println(~len(m)~)','0','Panics|Compile error','A nil map has length zero; no write occurs here.','m==nil|m')),
 L('structs','Struct values and pointers','Struct assignment copies fields, though fields such as slices may still reference shared storage. & obtains an address and * dereferences a pointer. Go has no general pointer arithmetic. Keyed struct literals document which fields are initialized.',
 S('type Config struct{Limit int}; a:=Config{Limit:${n}}; b:=a; b.Limit=0; fmt.Println(~a.Limit~)','${n}','0|Compile error','The struct value is copied, so its int field is independent.','b.Limit|0'),
 S('n:=${n}; p:=~&n~; *p+=1; fmt.Println(n)','${next}','${n}|Compile error','The pointer permits updating the original integer.','n|*n'),
 S('type Item struct{Name string}; x:=Item{~Name~:"${word}"}; fmt.Println(x.Name)','${word}','Compile error|Empty string','A keyed literal names the field it initializes.','name|Value'),
 S('type Item struct{N int}; p:=&Item{N:${n}}; fmt.Println(~p.N~)','${n}','Compile error|An address','Field selection automatically dereferences this struct pointer.','&p|p')),
 L('methods','Receiver types and method sets','Methods are functions with a receiver. Value receivers receive copies; pointer receivers can mutate the original. Calls may implicitly take an address for addressable values, but interface conformance still depends on method sets.',
 S('// Package-scope declarations:\ntype Counter struct{N int}\nfunc(c ~*Counter~) Inc(){c.N++}','Inc can update the caller Counter','Inc only mutates a copy|Counter becomes immutable','A pointer receiver permits mutation of the pointed-to value.','Counter|int','What does this receiver allow?'),
 S('// Package-scope declarations:\ntype Label string\nfunc(l Label) Text() string {return ~string(l)~}','Returns the label as a built-in string','Returns an address|Creates a goroutine','A named string-based type can define methods and explicitly convert to string.','l|&l','What does Text return?'),
 S('type Counter struct{N int}; c:=Counter{N:${n}}; change:=func(x Counter){x.N=0}; change(c); fmt.Println(~c.N~)','${n}','0|Compile error','Passing a struct value copies it, like a value receiver.','0|c.N+1'),
 S('type Counter struct{N int}; c:=Counter{N:${n}}; change:=func(x *Counter){x.N++}; change(~&c~); fmt.Println(c.N)','${next}','${n}|Compile error','The function receives a pointer to the original struct.','c|*c')),
 L('interfaces','Implicit interfaces and typed nil','A type implements an interface by having its methods; no implements declaration is needed. An interface holds a dynamic type and value. A typed nil pointer inside an interface makes the interface non-nil. Comma-ok assertions avoid a panic when the dynamic type differs.',
 S('var x any="${word}"; s,ok:=x.~(string)~; fmt.Println(s,ok)','${word} true','Empty string false|Compile error','The assertion checks the dynamic type and extracts its string value.','(int)|string'),
 S('var x any=${n}; _,ok:=x.~(string)~; fmt.Println(ok)','false','true|Panics','The two-result assertion reports failure without panicking.','(int)|(any)'),
 S('var p *int=nil; var x any=p; fmt.Println(~x==nil~)','false','true|Compile error','x has a dynamic type *int even though its stored pointer is nil.','p==nil|x!=nil'),
 S('var x any="${word}"; switch v:=x.~(type)~ {case string:fmt.Println(v);default:fmt.Println("other")}','${word}','other|Compile error','A type switch branches on the interface dynamic type.','(string)|type')),
 L('errors','Error values and wrapping','Errors are ordinary values, usually returned alongside a result. Check err before consuming a result whose validity depends on it. fmt.Errorf with %w wraps an error; errors.Is follows wrapping relationships. Do not compare error message strings when identity matters.',
 S('_,err:=strconv.Atoi("bad"); fmt.Println(~err!=nil~)','true','false|Compile error','Invalid decimal input produces a non-nil error.','err==nil|false'),
 S('base:=errors.New("${word}"); err:=fmt.Errorf("load: ~%w~",base); fmt.Println(errors.Is(err,base))','true','false|Compile error','%w preserves the wrapped error relationship for errors.Is.','%v|%s'),
 S('err:=errors.~New~("${word}"); fmt.Println(err.Error())','${word}','nil|Compile error','New creates an error with the given message.','Is|As'),
 S('f:=func()(int,error){return ${n},nil}; n,err:=f(); if err==~nil~ {fmt.Println(n)}','${n}','No output|Compile error','A nil error denotes success in this result/error convention.','true|false')),
 L('defer','Deferred cleanup and argument timing','defer schedules a call for the surrounding function return. Arguments are evaluated immediately, and deferred calls execute in reverse order. This supports file closure and unlocking, but deferring inside a long loop keeps resources until the function exits.',
 S('defer fmt.Println("last"); fmt.Println(~"${word}"~)','${word}\nlast','last\n${word}|last','The deferred print runs after the ordinary print at function exit.','"last"|"first"'),
 S('n:=${n}; defer fmt.Println(~n~); n++','${n}','${next}|Compile error','The argument n is evaluated when the defer statement executes.','n+1|0'),
 S('defer fmt.Println("first"); ~defer~ fmt.Println("second")','second\nfirst','first\nsecond|Compile error','Deferred calls are executed in last-in-first-out order.','go|return'),
 S('n:=${n}; defer ~func(){fmt.Println(n)}()~; n++','${next}','${n}|Compile error','The deferred closure reads the captured variable when it eventually runs.','fmt.Println(n)|fmt.Println(0)')),
 L('packages','Exports, module paths, and dependencies','Names beginning with an uppercase letter are exported from a package. Imports refer to package paths, while modules govern dependency versions. go.sum records dependency checksums, not source code. Keep package APIs small and avoid import cycles.',
 S('// In package config:\ntype Settings struct{~Limit~ int}','Limit is exported','Limit is private|Limit is a constant','An uppercase initial makes the field accessible to importing packages.','limit|_limit','What visibility does the field have?'),
 S('// go.mod:\n~module~ example.com/${word}','Declares the module path','Declares an executable entry point|Imports fmt','The module directive establishes the prefix of package import paths in this module.','package|import','What does this file declare?'),
 S('$ go mod ~tidy~','Reconciles module requirements with source imports','Formats every Go file|Publishes the module','tidy adds needed requirements and removes unused ones.','init|download','What maintenance operation runs?'),
 S('import ~"fmt"~','Imports the standard formatting package','Runs a formatter immediately|Downloads a third-party framework','An import makes package APIs available to this source file.','fmt|"main"','What does this declaration do?')),
 L('closures','Closures and function values','Functions can be passed and returned. Closures capture variables, so a later call can observe updated state. Keep capture lifetime separate from concurrent access safety. Functions are comparable only to nil, not to arbitrary other functions.',
 S('n:=${n}; f:=func()int{return n}; n++; fmt.Println(~f()~)','${next}','${n}|Compile error','The closure reads the captured variable after its update.','n-1|f'),
 S('apply:=func(f func(int)int,n int)int{return f(n)}; fmt.Println(apply(~func(x int)int{return x+1}~,${n}))','${next}','${n}|Compile error','The callback is a value passed to another function.','nil|${n}'),
 S('var f func(); fmt.Println(~f==nil~)','true','false|Compile error','The zero value of a function variable is nil.','f()!=nil|f'),
 S('makeNext:=func()func()int{n:=${n};return func()int{n++;return n}}; next:=makeNext(); fmt.Println(~next()~)','${next}','${n}|Compile error','The returned closure retains its captured state after the factory returns.','makeNext()|next')),
 L('generics','Type parameters and constraints','Generic functions express shared operations with compile-time constraints. comparable permits equality and map keys. A constraint with ~int includes named types whose underlying type is int. Generic APIs should state only the operations they actually require.',
 S('// Package-scope function:\nfunc Same[T ~comparable~](a,b T)bool{return a==b}','Accepts types supporting equality','Accepts every slice type|Uses reflection for equality','comparable is the constraint needed by == on type parameters.','any|interface{}','What contract does Same require?'),
 S('// Package-scope function:\nfunc Identity[T any](x T) ~T~ {return x}','Returns the same concrete type as its input','Always returns any|Converts its input to string','The return T preserves the type parameter relationship.','string|int','What type relationship is expressed?'),
 S('// Package-scope function:\nfunc Bump[T interface{~__TILDE__int~}](n T)T{return n+1}','Accepts int and named types with underlying int','Accepts all strings|Accepts only the exact built-in int','The tilde term includes types whose underlying type is int.','int|string','Which inputs satisfy the constraint?'),
 S('// Package-scope function:\nfunc First[T any](xs ~[]T~)T{return xs[0]}','Requires a slice and returns its element type','Accepts any single value|Guarantees empty input is safe','The signature preserves element type but xs[0] still needs a nonempty input.','T|map[string]T','What does this API promise?')),
 L('goroutines','Goroutines and communication','go starts a concurrent function call; main does not wait automatically. Channels communicate typed values and can synchronize completion. A blocked unbuffered send needs a receiver. Concurrency is not a guarantee of parallel execution.',
 S('ch:=make(chan int); ~go~ func(){ch<-${n}}(); fmt.Println(<-ch)','${n}','Deadlocks|Compile error','The sender runs concurrently while the receiver waits for its value.','defer|return'),
 S('ch:=make(chan string,1); ch<-"${word}"; fmt.Println(~<-ch~)','${word}','Deadlocks|Compile error','The one-slot buffer accepts a send before the receive begins.','ch|len(ch)'),
 S('done:=make(chan bool); go func(){fmt.Println("${word}");done<-true}(); ~<-done~','${word}','Always no output|Compile error','The receive keeps main alive until the worker has printed and signaled.','close(done)|len(done)'),
 S('ch:=make(chan int,2); ch<-${n}; fmt.Println(~len(ch)~)','1','2|${n}','len reports queued elements, not the channel capacity.','cap(ch)|<-ch')),
 L('channels','Channel closure and select','The sending side usually owns channel closure. A receive from a closed, drained channel returns the zero value and false. Sending to a closed channel panics. select chooses a ready operation; default makes it nonblocking, and a nil channel case is disabled.',
 S('ch:=make(chan int); ~close~(ch); n,ok:=<-ch; fmt.Println(n,ok)','0 false','0 true|Deadlocks','A closed empty channel immediately returns its zero value and false.','cap|len'),
 S('ch:=make(chan int,1); ch<-${n}; close(ch); for n:=~range ch~ {fmt.Println(n)}','${n}','Deadlocks|No output','range receives buffered values and stops once the closed channel is drained.','ch|<-ch'),
 S('ch:=make(chan int); select {case <-ch:fmt.Println("ready"); ~default~:fmt.Println("idle")}','idle','ready|Deadlocks','With no ready channel operation, default runs immediately.','else|case'),
 S('var ch chan int; select {case ch<-${n}:fmt.Println("sent"); ~default~:fmt.Println("disabled")}','disabled','sent|Panics','A nil-channel send cannot proceed, so the default arm is selected.','else|case')),
 L('context','Cancellation and shared state','Context carries deadlines and cancellation through call boundaries. Canceling a context is a signal, not forced termination; workers must observe Done. Mutex protects shared invariants, and a WaitGroup waits for registered work. Run the race detector to find exercised data races.',
 S('ctx,cancel:=context.WithCancel(context.Background()); ~cancel()~; fmt.Println(ctx.Err()==context.Canceled)','true','false|Compile error','Canceling sets the context error to Canceled.','context.Background()|ctx.Value("x")'),
 S('ctx,cancel:=context.WithCancel(context.Background()); cancel(); select {case ~<-ctx.Done()~:fmt.Println("stopped")}','stopped','Deadlocks|Compile error','Done is closed on cancellation, making its receive ready.','ctx.Err()|ctx.Done()'),
 S('var mu sync.Mutex; n:=${n}; mu.~Lock()~; n++; mu.Unlock(); fmt.Println(n)','${next}','${n}|Deadlocks','Lock and Unlock delimit a protected critical section.','TryLock()|Unlock()'),
 S('$ go test ~-race~ ./...','Tests with data-race instrumentation','Proves all schedules race-free|Only benchmarks tests','The race detector can report races reached during this execution; unexecuted paths are not proved safe.','-v|-count=1','What extra checking is enabled?')),
 L('testing','Tests and standard-library I/O boundaries','Tests live in _test.go and take *testing.T. Table-driven cases keep inputs and expectations visible. io.Reader lets parsing logic work with files or in-memory strings. io.ReadAll returns an error as well as bytes; handle it at the boundary. No web framework is needed to learn these contracts.',
 S('// In size_test.go:\nfunc ~TestSize~(t *testing.T){if len("${word}")!=${length}{t.Fatal("length")}}','A test discovered by go test','A benchmark only|A normal executable entry point','The Test prefix and *testing.T signature identify a test function.','testSize|main','How is this function discovered?'),
 S('r:=strings.~NewReader~("${word}"); b,err:=io.ReadAll(r); fmt.Println(string(b),err==nil)','${word} true','Empty string false|Compile error','An in-memory reader exercises the io.Reader contract without a file.','NewReplacer|ToUpper'),
 S('_,err:=os.Stat("absent-file-for-example"); fmt.Println(os.~IsNotExist~(err))','true','false|Compile error','Assume this path is absent. IsNotExist recognizes the missing-file error.','IsPermission|IsTimeout','Assuming the path does not exist, what prints?'),
 S('var wg sync.WaitGroup; wg.Add(1); go func(){defer wg.~Done()~;fmt.Println("${word}")}(); wg.Wait()','${word}','Deadlocks|No output','Add registers work before starting it; Done completes it and releases Wait.','Wait()|Add(1)')),
 ]
